"""Private browser-only manual JRA roster-number correspondence; no official verification claim."""
HTML = "<section id=\"manualNumberSection\"><h2>3. JRAの確定馬番と想定馬名を照合（手入力）</h2><p class=\"warning\">JRA公式の出馬表で馬番と馬名を確認して転記するための本人用メモやで。アプリが公式サイトに接続して確認した証明ではありません。取消・枠順・馬場・発走時刻の最終確認は別途必要。自動予想・購入はしません。</p><label for=\"numberRace\">照合するレース</label><select id=\"numberRace\"><option value=\"\">先に上の日付・競馬場を選んでな</option></select><label for=\"numberPaste\">馬番と馬名（1行ずつ、馬番は1～18）</label><textarea id=\"numberPaste\" rows=\"5\" maxlength=\"4000\" placeholder=\"1 テストホースA&#10;2 テストホースB&#10;3 テストホースC\"></textarea><button id=\"compareNumbers\" type=\"button\">想定馬名と照合する</button><p id=\"numberMessage\" class=\"hint\" role=\"status\">照合だけなら保存しません。馬番・馬名が不一致なら差分を表示します。</p><div id=\"numberPreview\" role=\"region\" aria-label=\"手入力した馬番と想定馬名の照合結果\"></div><button id=\"saveNumbers\" type=\"button\" disabled>確認した馬番の対応を端末に保存</button><p class=\"hint\">保存しても「JRA公式確認済み」にはなりません。購入記録・3連単フォーメーションにも反映しません。</p><h3>保存済みの馬番対応</h3><p id=\"storedNumberMessage\" class=\"hint\">まだこのレースの照合メモはありません。</p><div id=\"storedNumberRows\"></div><a id=\"openDraftForRace\" href=\"/my-tickets\">このレースの3連単下書きへ進む（手動）</a><p class=\"hint\">開催日・競馬場・Rだけを引き継ぎます。馬番・想定馬名は送信せず、買い目は自動作成しません。</p><button id=\"deleteNumbers\" type=\"button\" class=\"secondary\">選択レースの馬番メモだけ削除</button></section>"
CSS = "#manualNumberSection h3{font-size:16px;margin:18px 0 5px}#manualNumberSection button:disabled{opacity:.42;cursor:not-allowed}#numberPreview p,#storedNumberRows p{margin:8px 0}#numberPreview{border-left:3px solid #8ba5bb;padding:0 12px}#storedNumberRows{padding:0 10px}.number-match{color:#b7e6c3}.number-diff{color:#ffdb9a}"
JS = "'use strict';\n// A deliberate, offline USER TRANSCRIPTION of a named race roster, not a JRA\n// verification service. No fetch, licensed data forwarding or betting actions.\n(function(){\nconst MAIL_KEY='keiba-nine-jrdb-personal-mail-v1';\nconst MAP_KEY='keiba-nine-owner-manual-numbers-v1';\nconst MAX_ROWS=18,MAX_RECORDS=576;\nconst $=id=>document.getElementById(id);\nconst make=(tag,t)=>{const x=document.createElement(tag);x.textContent=String(t);return x;};\nconst key=(date,track,race)=>date+'|'+track+'|'+race;\nfunction sourceMark(r){return JSON.stringify([r.postTime,r.expected,r.horses]);}\nfunction current(){\n const meetingKey=$('chooseMeeting').value;\n if(!/^\\d{4}-\\d{2}-\\d{2}\\|(?:札幌|函館|福島|新潟|東京|中山|中京|京都|阪神|小倉)$/.test(meetingKey))return null;\n const all=JSON.parse(localStorage.getItem(MAIL_KEY)||'[]');\n if(!Array.isArray(all))return null;\n const m=all.find(x=>x&&x.date+'|'+x.track===meetingKey&&x.kind==='jrdb-provisional');\n const raceNo=Number($('numberRace').value);\n if(!m||!Number.isInteger(raceNo)||raceNo<1||raceNo>12)return null;\n const r=m.races.find(x=>x.race===raceNo);\n if(!r||!Array.isArray(r.horses)||r.horses.length!==r.expected)return null;\n return {date:m.date,track:m.track,race:raceNo,source:r};\n}\nfunction parseNumbers(raw){\n if(typeof raw!=='string'||raw.length>4000||!raw.trim())\n  throw Error('馬番と馬名を1行ずつ入力してな。');\n const circles='①②③④⑤⑥⑦⑧⑨⑩⑪⑫⑬⑭⑮⑯⑰⑱';\n const clean=raw.replace(/[①-⑱]/g,x=>' '+(circles.indexOf(x)+1)+' ').normalize('NFKC');\n const lines=clean.split(/\\r?\\n/).map(x=>x.trim()).filter(Boolean);\n if(!lines.length||lines.length>MAX_ROWS)\n  throw Error('1レース1～18頭までの馬番と馬名を貼ってな。');\n const byNo=new Set(),byName=new Set(),out=[];\n for(const line of lines){\n  const found=/^(\\d{1,2})(?:番)?(?:\\s+|\\s*[：:、,・]\\s*)([^\\s:：、,・]+)$/.exec(line);\n  if(!found)throw Error('「1 馬名」「② 馬名」の形式で、1頭を1行にしてな。');\n  const n=Number(found[1]),name=found[2].trim();\n  if(!Number.isInteger(n)||n<1||n>18||!name||name.length>35)\n   throw Error('馬番は1～18、馬名は35文字以内にしてな。');\n  if(byNo.has(n)||byName.has(name))throw Error('同じ馬番または馬名が重複しています。');\n  byNo.add(n);byName.add(name);out.push({number:n,name});\n }\n out.sort((a,b)=>a.number-b.number);\n return out;\n}\nfunction check(reference,rows){\n const names=new Set(reference.horses),provided=new Set(rows.map(r=>r.name));\n const matched=rows.filter(r=>names.has(r.name));\n const absent=reference.horses.filter(n=>!provided.has(n));\n const extra=rows.filter(r=>!names.has(r.name)).map(r=>r.name);\n return {matched:matched.length,absent,extra,rows,sourceMark:sourceMark(reference)};\n}\nfunction validSaved(x){\n if(!x||!/^20\\d{2}-\\d{2}-\\d{2}$/.test(x.date)||\n    !['札幌','函館','福島','新潟','東京','中山','中京','京都','阪神','小倉'].includes(x.track)||\n    !Number.isInteger(x.race)||x.race<1||x.race>12||\n    typeof x.sourceMark!=='string'||x.sourceMark.length>1500||\n    !Array.isArray(x.rows)||!x.rows.length||x.rows.length>18)return false;\n const nums=new Set(),names=new Set();\n for(const r of x.rows){\n  if(!r||!Number.isInteger(r.number)||r.number<1||r.number>18||\n     typeof r.name!=='string'||r.name.length<1||r.name.length>35||\n     nums.has(r.number)||names.has(r.name))return false;\n  nums.add(r.number);names.add(r.name);\n }\n return true;\n}\nfunction readSaved(){\n try{\n  const values=JSON.parse(localStorage.getItem(MAP_KEY)||'[]');\n  return Array.isArray(values)?values.slice(0,MAX_RECORDS).filter(validSaved):[];\n }catch(_){return [];}\n}\nlet records=readSaved(),pending=null;\nfunction renderStored(){\n const box=$('storedNumberRows');box.replaceChildren();\n const selected=current();\n $('deleteNumbers').disabled=!selected;\n const link=$('openDraftForRace');\n if(selected){\n  link.href='/my-tickets#select=v1&date='+encodeURIComponent(selected.date)+\n   '&track='+encodeURIComponent(selected.track)+'&race='+selected.race;\n }else link.href='/my-tickets';\n if(!selected){$('storedNumberMessage').textContent='開催日・競馬場・レースを選んでな。';return;}\n const saved=records.find(x=>key(x.date,x.track,x.race)===key(selected.date,selected.track,selected.race));\n if(!saved){$('storedNumberMessage').textContent='このレースの手入力した馬番メモはまだありません。';return;}\n const stale=saved.sourceMark!==sourceMark(selected.source);\n $('storedNumberMessage').textContent=stale?\n  '注意：JRDB想定メールが更新されたため、保存済み馬番メモの再照合が必要。前の内容を自動で変更してへん。':\n  '本人の手入力で保存した馬番対応。JRA自動照合済みではありません。';\n const names=new Set(selected.source.horses);\n for(const entry of saved.rows){\n  const line=make('p',entry.number+'番 '+entry.name+(names.has(entry.name)?'':'（想定馬名にない）'));\n  box.append(line);\n }\n}\nfunction refresh(){\n const old=$('numberRace').value;\n const selected=$('chooseMeeting').value;\n let races=[];\n try{\n  const data=JSON.parse(localStorage.getItem(MAIL_KEY)||'[]');\n  const m=Array.isArray(data)?data.find(x=>x&&x.date+'|'+x.track===selected):null;\n  races=m&&Array.isArray(m.races)?m.races.slice().sort((a,b)=>a.race-b.race):[];\n }catch(_){races=[];}\n const selector=$('numberRace');selector.replaceChildren();\n const placeholder=make('option',races.length?'レースを選んでな':'上の開催を先に選んでな');\n placeholder.value='';selector.append(placeholder);\n for(const race of races){\n  const option=make('option',race.race+'R');option.value=String(race.race);selector.append(option);\n }\n selector.value=races.some(x=>String(x.race)===old)?old:\n  (races[0]?String(races[0].race):'');\n clearPending();renderStored();\n}\nfunction clearPending(){\n pending=null;$('saveNumbers').disabled=true;$('numberPreview').replaceChildren();\n}\nconst chooser=$('chooseMeeting'),previous=chooser.onchange;\nchooser.onchange=()=>{if(typeof previous==='function')previous();refresh();};\n$('numberRace').onchange=()=>{clearPending();$('numberPaste').value='';renderStored();};\n$('numberPaste').oninput=()=>{clearPending();};\n$('compareNumbers').onclick=()=>{\n clearPending();\n const selected=current();\n if(!selected){$('numberMessage').textContent='先に開催日・競馬場・Rを選んでな。';return;}\n try{\n  const rows=parseNumbers($('numberPaste').value);\n  const comparison=check(selected.source,rows);\n  const preview=$('numberPreview');\n  preview.append(make('p',selected.date+' '+selected.track+selected.race+'R：'+\n    '想定'+selected.source.expected+'頭／馬番付き'+rows.length+'頭／馬名一致'+comparison.matched+'頭'));\n  if(comparison.absent.length)preview.append(make('p','想定にあるが貼付にない：'+comparison.absent.join('、')));\n  if(comparison.extra.length)preview.append(make('p','想定にないが貼付にある：'+comparison.extra.join('、')));\n  if(!comparison.absent.length&&!comparison.extra.length)\n   preview.append(make('p','馬名は全件一致。ただし元の出馬表の真偽・馬番は自動検証してへん。'));\n  for(const entry of rows)preview.append(make('p',entry.number+'番 '+entry.name));\n  pending={...selected,...comparison,rows};\n  $('saveNumbers').disabled=false;\n  $('numberMessage').textContent='差異を確認してな。保存ボタンを押すまでは端末に反映しません。';\n }catch(err){$('numberMessage').textContent='照合できません：'+(err&&err.message||'入力形式を確認してな。');}\n};\n$('saveNumbers').onclick=()=>{\n const live=current();\n if(!pending||!live||live.date!==pending.date||live.track!==pending.track||\n    live.race!==pending.race||sourceMark(live.source)!==pending.sourceMark){\n  clearPending();$('numberMessage').textContent='想定資料か選択レースが変わったため、もう一度照合してな。';return;\n }\n const mismatch=pending.absent.length+pending.extra.length;\n const existing=records.find(x=>key(x.date,x.track,x.race)===key(live.date,live.track,live.race));\n if(!confirm(live.date+' '+live.track+live.race+'Rの馬番対応を本人の端末に保存しますか？\\n'+\n   (mismatch?'想定メールとの差異が'+mismatch+'件あります。取消・追加と決めつけず、JRA出馬表と照合してな。\\n':'想定馬名は一致。ただしJRA公式照合をアプリが保証するものではありません。\\n')+\n   (existing?'このレースの前の馬番メモを上書きします。':'新規の手入力メモです。')+\n   '\\n3連単下書きと実購入記録には影響しません。'))return;\n const revised=records.filter(x=>key(x.date,x.track,x.race)!==key(live.date,live.track,live.race));\n if(revised.length>=MAX_RECORDS){\n  $('numberMessage').textContent='メモ上限のため追加できません。不要なメモを削除してな。';return;\n }\n revised.push({date:live.date,track:live.track,race:live.race,\n               sourceMark:pending.sourceMark,rows:pending.rows});\n try{localStorage.setItem(MAP_KEY,JSON.stringify(revised));\n  records=revised;clearPending();renderStored();\n  $('numberMessage').textContent='馬番対応を端末内に保存したで。JRA公式検証や3連単生成には進んでへん。';\n }catch(_){$('numberMessage').textContent='端末に保存できませんでした。前のメモは残しています。';}\n};\n$('deleteNumbers').onclick=()=>{\n const selected=current();if(!selected)return;\n const k=key(selected.date,selected.track,selected.race);\n if(!records.some(x=>key(x.date,x.track,x.race)===k))return;\n if(!confirm(selected.date+' '+selected.track+selected.race+'Rの手入力馬番メモだけを削除しますか？'))return;\n const revised=records.filter(x=>key(x.date,x.track,x.race)!==k);\n try{localStorage.setItem(MAP_KEY,JSON.stringify(revised));\n  records=revised;clearPending();renderStored();\n  $('numberMessage').textContent='このレースの手入力馬番メモだけ削除したで。';\n }catch(_){$('numberMessage').textContent='削除を保存できませんでした。';}\n};\nfor(const id of ['deleteMeeting','clearAll']){\n const btn=$(id),prior=btn.onclick;\n btn.onclick=()=>{if(typeof prior==='function')prior();refresh();};\n}\nrefresh();\n})();"
